        check(ImageQuality.sizeScale(1000)<ImageQuality.sizeScale(4096)&&ImageQuality.sizeScale(8000)==1,"Adaptive grain scales down for small cropped outputs without exceeding the style maximum");check(ImageQuality.outputEdge(4096,3072,230f/85,3f/4)<1600&&ImageQuality.outputEdge(4096,3072,1,1)==3072,"Planned grain reference follows digital crop and capture aspect rather than preview resolution");check(ImageQuality.editEdge(4096,3072,16f/9)==4096&&ImageQuality.editEdge(3072,4096,3f/4)==4096,"Editor grain reference respects already-upright horizontal and vertical originals");check(ImageQuality.grainShade(0)<ImageQuality.grainShade(.3f)&&ImageQuality.grainShade(.7f)==1,"Adaptive grain suppresses dark-region buildup without amplifying bright regions");
        check(ImageQuality.skin(.78f,.59f,.45f)>0&&ImageQuality.skin(.2f,.7f,.8f)==0&&ImageQuality.skin(.4f,.4f,.4f)==0,"Soft skin-color mask excludes blue/cyan and neutral colors");
        float[] grey=ImageQuality.grey(.45f,.5f,.55f);check(near(.45f*grey[0],.5f*grey[1])&&near(.5f*grey[1],.55f*grey[2]),"Gray-card gains neutralize a small measured color cast");
        boolean rejects=false;try{ImageQuality.grey(.01f,.02f,.02f);}catch(IllegalArgumentException expected){rejects=true;}check(rejects,"Gray-card estimates reject an underexposed sample");
        float[] bounded=ImageQuality.grey(.2f,.5f,.7f);check(bounded[0]<=1.15f&&bounded[2]>=.85f,"Gray-card gains remain inside conservative per-lens bounds");
        check(ImageQuality.previewBudget(230,0,1)<=1920L*1080&&ImageQuality.previewBudget(230,0,0)>ImageQuality.previewBudget(230,0,1),"Fluid mode reduces only the advertised preview budget while detail mode preserves long-focal detail");
        check(ImageQuality.optical(14).contains("原生光学")&&ImageQuality.optical(135).contains("85mm 光学")&&ImageQuality.optical(50).contains("23mm 光学"),"Focal descriptions expose the correct optical base for every digital extension");
        check(RawPolicy.pair(88,88)&&!RawPolicy.pair(0,0)&&!RawPolicy.pair(88,89),"DNG requires a positive exact RAW-image and capture-result timestamp match");
        check(RawPolicy.size(8192,6144)==false&&RawPolicy.size(8000,6000)&&!RawPolicy.size(20000,10000),"RAW allocation rejects unsupported oversized sensor outputs");
        check(RawPolicy.orientation(0)==1&&RawPolicy.orientation(90)==6&&RawPolicy.orientation(180)==3&&RawPolicy.orientation(270)==8,"DNG stores all four sensor-to-upright orientation tags");
        check(CaptureInfo.shutter(10000000).equals("1/100s")&&CaptureInfo.shutter(2000000000L).equals("2.0s")&&CaptureInfo.shutter(0).contains("未返回"),"Capture details distinguish measured shutter values from missing metadata");
        int w=41,h=31;int[] source=new int[w*h];for(int i=0;i<source.length;i++)source[i]=0xff000000|((i*71%256)<<16)|((i*23%256)<<8)|(i*137%256);Bitmap input=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);input.setPixels(source,0,w,0,0,w,h);boolean parity=true,neutralMono=true;int largest=0;
        for(int id=0;id<51;id++){Film.Settings s=new Film.Settings();s.stock=id;s.grain=0;s.skin=.4f;s.highlights=.4f;s.red=1.04f;s.green=.99f;s.blue=.96f;s.contrast=1.03f;s.strength=.7f;int[] actual=pixels(Film.develop(input,s));for(int x=0;x<w;x++){int i=h/2*w+x,expected=shader(source[i],x,h/2,w,h,s);for(int shift=0;shift<24;shift+=8){int delta=Math.abs(((actual[i]>>shift)&255)-((expected>>shift)&255));largest=Math.max(largest,delta);parity&=delta<=1;}}}
        check(parity,"Actual CPU exports match the independent GPU-formula model within one level across all 51 looks");
        Film.Settings mono=new Film.Settings();mono.stock=4;mono.grain=0;mono.skin=1;for(int p:pixels(Film.develop(input,mono)))neutralMono&=((p>>16)&255)==((p>>8)&255)&&((p>>8)&255)==(p&255);check(neutralMono,"Skin protection cannot add color back into monochrome recipes");
        Film.Settings bypass=copy.copy();bypass.strength=0;bypass.exposure=0;check(Arrays.equals(source,pixels(Film.develop(input,bypass))),"Zero film strength still returns untouched source despite quality and calibration controls");
        float[] normal=Film.parameters(legacy),soft=Film.parameters(copy);check(soft[16]>normal[16]&&curve(.95f,0,soft)<1.2f,"Highlight shoulder remains finite after combined calibration and highlight softening");
        File dir=Files.createTempDirectory(Paths.get(args[0]),"workflows-").toFile();RecipeStore recipes=new RecipeStore(dir);recipes.add("周末暖调",copy);List<RecipeStore.Recipe> all=recipes.list();check(all.size()==1&&all.get(0).name.equals("周末暖调")&&near(all.get(0).settings.highlights,.5f),"Named recipes persist color and quality parameters through JSON roundtrip");
        check(all.get(0).settings.red==1&&all.get(0).settings.iso==0&&all.get(0).settings.calibrationEv==0,"Recipe application never imports device calibration or the old capture ISO");
        check(recipes.merge(recipes.encode(all))==0&&recipes.list().size()==1,"Importing the same recipe library twice does not duplicate entries");
        byte[] before=Files.readAllBytes(new File(dir,"recipes.json").toPath());boolean blocked=false;try{recipes.add("",legacy);}catch(Exception expected){blocked=true;}check(blocked&&Arrays.equals(before,Files.readAllBytes(new File(dir,"recipes.json").toPath())),"Invalid recipe names cannot partially overwrite the saved library");
        JSONObject hostile=new JSONObject(recipes.encode(all));hostile.getJSONArray("recipes").getJSONObject(0).getJSONObject("settings").put("stock",999);blocked=false;try{recipes.merge(hostile.toString());}catch(Exception expected){blocked=true;}check(blocked&&recipes.list().size()==1,"Unknown base-film IDs reject the entire recipe import");
        for(int i=1;i<50;i++)recipes.add("配方 "+i,legacy);before=Files.readAllBytes(new File(dir,"recipes.json").toPath());blocked=false;try{recipes.add("超过上限",legacy);}catch(Exception expected){blocked=true;}check(blocked&&Arrays.equals(before,Files.readAllBytes(new File(dir,"recipes.json").toPath())),"Recipe capacity errors leave all 50 existing presets intact");
        recipes.remove(all.get(0).id);check(recipes.list().size()==49,"Deleting a recipe removes only its stable identifier");
